  if (typeof name !== 'string') {
    return res.status(400).json({ error: 'Name field must be a string' });
  }

  // If validation passes, send success response
  res.status(201).json({ message: 'User created successfully', user: { name } });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

